      SUBROUTINE RSHTORCC     TRANSFERS MATRIX RSH TO RCC ----------------------------------------------------------------------      INCLUDE 'ELM17A.CIN'      INCLUDE 'R.CIN'      INCLUDE 'RC3.CIN'      INCLUDE 'T.CIN'      INCLUDE 'TC3.CIN'      INCLUDE 'U.CIN'      INCLUDE 'UC3.CIN'C      DO 10 J = 1, 36   10 RL(J) = RSHL(J)      IF (NORD1 .GE. 2) THEN        DO 20 J = 1, 105   20   TL(J) = TSHL(J)      ENDIF      IF (NORD1 .GE. 3) THEN        DO 30 J = 1, 280   30   UL(J) = USHL(J)      ENDIF      RETURN      END